using System.Numerics;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for maximum throughput on large spans.
    /// </summary>
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (!Vector.IsHardwareAccelerated || values.Length < Vector<float>.Count)
            return FindMinMaxScalar(values);

        ReadOnlySpan<Vector<float>> vectors = MemoryMarshal.Cast<float, Vector<float>>(values);

        var vMin = vectors[0];
        var vMax = vectors[0];

        // Process two vectors per iteration to increase ILP
        int i = 1;
        int vectorCount = vectors.Length;
        for (; i + 1 < vectorCount; i += 2)
        {
            vMin = Vector.Min(vMin, vectors[i]);
            vMax = Vector.Max(vMax, vectors[i]);
            vMin = Vector.Min(vMin, vectors[i + 1]);
            vMax = Vector.Max(vMax, vectors[i + 1]);
        }
        for (; i < vectorCount; i++)
        {
            vMin = Vector.Min(vMin, vectors[i]);
            vMax = Vector.Max(vMax, vectors[i]);
        }

        // Reduce vector lanes to scalar
        float min = vMin[0];
        float max = vMax[0];
        for (int lane = 1; lane < Vector<float>.Count; lane++)
        {
            if (vMin[lane] < min) min = vMin[lane];
            if (vMax[lane] > max) max = vMax[lane];
        }

        // Handle remaining elements not covered by full vectors
        int processed = vectorCount * Vector<float>.Count;
        for (int j = processed; j < values.Length; j++)
        {
            if (values[j] < min) min = values[j];
            if (values[j] > max) max = values[j];
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }
}

